import {renderRolePage,roleSubtitle} from './role-views.js';
import {demoUsers,allUsers,addRoleFixtures,roleNavigation,allowedRoute,scopedData,canAct,requireRecord,addTechnicianFixtures,activeUser,isTechnician,assignedJobs,requireJob,technicianRoute,technicianData} from './access.js';
import {technicianOverview,technicianDetail,technicianSettings,techTable} from './technician.js';
import { workspaceSettings, applyWorkspaceSettings, renderSettings, settingsTabs } from './settings.js';
import { pageSubtitle } from './page-copy.js';
import { enhanceTables } from './tables.js';
import { renderOverview, overviewModel, reportData, dsIcon, figmaAssets, moduleTitles, moduleIcons, navIcons } from './overview.js';
import {modules,roles,flows,workflowFor,seed,stageName,complete,severity,transition,metrics,TODAY} from './domain.js';
import {openStore,save} from './store.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<img class="icon ${cls}" src="/public/icons/${name}.svg" alt="" width="20" height="20">`;
const link=(text,hash,cls='')=>`<a class="${cls}" href="#${hash}">${text}</a>`;
const button=(text,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const badge=(text,tone)=>`<span class="badge ${tone||(/Critical|Failed|Returned/.test(text)?'red':/Warning|Degraded|Intermittent|Needs attention|pending|gap|Reported|required/i.test(text)?'amber':'green')}"><span></span>${esc(text)}</span>`;
const roleLabel=role=>role==='National coordinator'?'National Coordinator':role.replace(/\b\w/g,c=>c.toUpperCase());
const money=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(n);
let profileOpen=false;
let settingsDraft=null,settingsSection='details';
let regionGeo=[],mapSelection='',mapZoom=1;
let state,geo,scope='All states',query='',lga='All LGAs',status='All statuses',menu=false,returnFocus,attachments=[];
let mod='schools',view='Overview',entityId='';
const dialog=$('#dialog');
const routes=()=>{let hash;try{hash=decodeURIComponent(location.hash.slice(1));}catch{hash='program/Overview';}let p=hash.split('/');mod=modules[p[0]]?p[0]:(state?.settings.defaultModule||'schools');view=p[1]||'Overview';entityId=p[2]||'';};
const go=(m,v='Overview',id='')=>`${m}/${v}${id?'/'+id:''}`;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
async function commit(next){await save(next);state=next;}
function openDialog(html){dialog.classList.remove('report-dialog');returnFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-top">${button('×','close','icon-btn','aria-label="Close dialog"')}</div>${html}`;enhanceTables(dialog);dialog.showModal();}
function closeDialog(){dialog.close();returnFocus?.focus();}
dialog.addEventListener('close',()=>returnFocus?.focus());
function selectedRecords(m=mod){return scopedData(state).records.filter(r=>(!m||r.module===m)&&(!(m==='program'&&/^P[1-8]$/.test(entityId))||r.pillar===Number(entityId.slice(1)))&&(scope==='All states'||r.state===scope)&&(status==='All statuses'||severity(r,state)===status)&&(!query||`${r.id} ${r.title} ${r.state}`.toLowerCase().includes(query.toLowerCase())));}
function selectedSchools(){return state.schools.filter(s=>(scope==='All states'||s.state===scope)&&(lga==='All LGAs'||s.lga===lga)&&(!query||`${s.id} ${s.name} ${s.state}`.toLowerCase().includes(query.toLowerCase())));}
function stat(label,value,sub,kind='normal'){return `<div class="stat"><div class="stat-label">${label}<span class="tiny-ring">↗</span></div><div class="stat-value">${value}</div><div class="stat-foot ${kind}">${sub}</div></div>`}
function panel(title,body,action='',className=''){return `<section class="panel ${className}"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`}
function recordLink(r){return go(r.module,'Record',r.id)}
function table(headers,rows,empty='No records match these filters.'){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty">${empty}</div></td></tr>`}</tbody></table></div>`}
function recordTable(records){return table(['Record / responsible work','State','Workflow stage','Priority',''],records.map(r=>[link(`<strong>${esc(r.title)}</strong><small>${r.id} · ${modules[r.module].name}</small>`,recordLink(r)),esc(r.state),badge(stageName(r),'neutral'),badge(severity(r,state)),link('Open ↗',recordLink(r),'text-link')]));}
function mapBlock(){
 const points=[{name:'Kaduna',x:272,y:173},{name:'Kano',x:301,y:109},{name:'Oyo',x:137,y:263}];
 let path='';if(geo?.[0]){const coords=geo[0].geometry.coordinates;const rings=geo[0].geometry.type==='MultiPolygon'?coords.flat():coords;path=rings.map(r=>r.map((p,i)=>`${i?'L':'M'}${40+(p[0]-2.5)*43},${325-(p[1]-4)*31}`).join(' ')+' Z').join(' ')}
 return `<div class="map"><div class="map-label"><span class="live-dot"></span> 3 demonstration states</div><svg viewBox="0 0 560 370" role="img" aria-label="Illustrative Nigeria map showing Kaduna, Kano and Oyo"><defs><pattern id="dots" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="#ced8d2"/></pattern></defs><rect width="560" height="370" fill="url(#dots)"/><path d="${path}" fill="#e7eee7" stroke="#bccdbf" stroke-width="1.4"/><text x="275" y="250" fill="#83a08e" font-size="13" letter-spacing="5">NIGERIA</text>${points.map(p=>`<g><circle cx="${p.x}" cy="${p.y}" r="19" fill="#fff" stroke="${scope===p.name?'#186b4b':'#b1c5b7'}" stroke-width="2"/><circle cx="${p.x}" cy="${p.y}" r="5" fill="#186b4b"/><text x="${p.x+26}" y="${p.y+5}" font-size="12" fill="#354b3d">${p.name}</text></g>`).join('')}</svg><div class="map-buttons">${points.map(p=>button(`${p.name} ↗`,'scope','map-pin',`data-state="${p.name}"`)).join('')}</div><span class="map-disclaimer">Illustrative geography · synthetic school locations</span></div>`;
}
function overview(){return renderOverview({state,module:mod,scope,geometry:regionGeo.length?regionGeo:geo,selection:mapSelection,zoom:mapZoom,ui:{button,link}});}
function searchable(){return view==='Evidence'||(mod==='program'&&['DLR readiness','Actions'].includes(view))||(mod==='schools'&&['Schools','Asset registry','Work orders'].includes(view))||(mod==='teachers'&&['Teacher profiles','Mentor observations'].includes(view))||(mod==='energy'&&['Energy passports','Construction'].includes(view))||(mod==='essence'&&['Cohorts & schedule','Practicum','Completion & follow-up'].includes(view))||(mod==='community'&&view!=='Community centres');}
function toolbar(){const recordsOnly=!['Schools','Asset registry','Teacher profiles','Evidence'].includes(view);return `<div class="toolbar"><div class="search-box">${icon('search')}<input id="search" aria-label="Search records" placeholder="Search records, schools, IDs…" value="${esc(query)}"></div><div class="filter-group">${recordsOnly?`<select id="status" aria-label="Priority filter">${['All statuses','Normal','Warning','Critical'].map(s=>`<option ${status===s?'selected':''}>${s}</option>`).join('')}</select>`:''}${button(`${icon('document')} Export CSV`,'export')}</div></div>`}
function schoolsView(){if(entityId)return schoolDetail();return panel('School directory',table(['School','State / LGA','Learners','Facility condition',''],selectedSchools().map(s=>[link(`<strong>${esc(s.name)}</strong><small>${s.id} · Synthetic school</small>`,go('schools','Schools',s.id)),`${s.state}<small>${s.lga}</small>`,s.students,badge(s.condition),link('View profile ↗',go('schools','Schools',s.id),'text-link')])),`<select id="lga" aria-label="LGA filter">${['All LGAs',...new Set(state.schools.filter(s=>scope==='All states'||s.state===scope).map(s=>s.lga))].map(x=>`<option ${x===lga?'selected':''}>${x}</option>`).join('')}</select>`);}
function schoolDetail(){const s=state.schools.find(s=>s.id===entityId);if(!s)return missing();return `<div class="record-banner"><div class="record-emblem">${icon('hat_graduation')}</div><div><p class="eyebrow">${s.id} · SYNTHETIC SCHOOL</p><h2>${s.name}</h2><p>${s.lga}, ${s.state} · ${s.students} learners</p></div>${badge(s.condition)}</div><div class="stats">${Object.entries(s.facilities).map(([k,v])=>stat(k,`<span class="small-value">${v}</span>`,'Facility profile')).join('')}</div>${assetTable(state.assets.filter(a=>a.schoolId===s.id))}${panel('Related work',recordTable(state.records.filter(r=>r.schoolId===s.id)))}`}
function assetTable(as){return panel('Asset health registry',table(['Asset','School','Condition','Warranty',''],as.map(a=>[link(`<strong>${a.name}</strong><small>${a.id}</small>`,go('schools','Asset registry',a.id)),esc(state.schools.find(s=>s.id===a.schoolId)?.name||a.schoolId),badge(a.condition),a.warranty,link('Health record ↗',go('schools','Asset registry',a.id),'text-link')])));}
function assetsView(){const a=state.assets.find(a=>a.id===entityId);if(entityId&&!a)return missing();if(!a)return assetTable(state.assets.filter(a=>(scope==='All states'||a.state===scope)&&(!query||`${a.name} ${a.id}`.toLowerCase().includes(query.toLowerCase()))));return `<div class="record-banner"><div class="record-emblem">${icon('settings')}</div><div><p class="eyebrow">ASSET HEALTH RECORD · ${a.id}</p><h2>${a.name}</h2><p>${a.state} · Warranty through ${a.warranty}</p></div>${badge(a.condition)}</div><div class="two-col">${panel('Asset passport',`<div class="content"><dl><dt>School</dt><dd>${link(esc(state.schools.find(s=>s.id===a.schoolId)?.name),go('schools','Schools',a.schoolId))}</dd><dt>Health record</dt><dd>${a.id}</dd><dt>Condition</dt><dd>${badge(a.condition)}</dd></dl>${button('Copy asset link','copy-link','small-btn')} <small>Stable asset address for QR labels</small></div>`)}${panel('Health timeline',timeline(a.history.length?a.history:[{label:'Asset registered in demonstration',actor:'School operations',at:'2026-11-10T09:00:00Z'}]))}</div>${panel('Linked maintenance',recordTable(state.records.filter(r=>r.assetId===a.id)),button('Report service issue','issue','small-btn',`data-id="${a.id}"`))}`;}
function timeline(events){return `<ol class="timeline">${[...events].reverse().map(e=>`<li><span class="timeline-dot"></span><strong>${esc(e.label)}</strong><p>${esc(e.actor||'System')} · ${new Date(e.at).toLocaleString('en-GB',{timeZone:state.personalPreferences?.[activeUser(state).id]?.timezone||'Africa/Lagos',dateStyle:'medium',timeStyle:'short'})}</p></li>`).join('')}</ol>`}
function teacherViews(){if(view==='Courses & guides')return courseCards();if(view==='Learning outcomes')return panel('Learning outcomes by school',`<p class="content muted">Illustrative aggregate snapshot. These values are independent of training completion and do not imply causation.</p>${table(['School','Learners assessed','Literacy · sample baseline','Numeracy · sample baseline'],selectedSchools().map(s=>[esc(s.name),Math.round(s.students*.8),`${55+Number(s.id.slice(-2))%20}%`,`${49+Number(s.id.slice(-2))%20}%`]))}`);if(view==='Mentor observations')return panel('Observation and coaching',recordTable(selectedRecords()));const t=state.teachers.find(t=>t.id===entityId);if(t)return `<div class="record-banner"><div class="avatar large">${t.name.slice(-2)}</div><div><p class="eyebrow">${t.id} · SYNTHETIC TEACHER</p><h2>${t.name}</h2><p>${t.course} · ${t.state}</p></div></div><div class="two-col">${panel('Development and coaching',recordTable(state.records.filter(r=>r.teacherId===t.id)))}${panel('Learning history',t.history.length?timeline(t.history):'<div class="empty">No completed training events yet.</div>')}</div>`;return panel('Teacher development profiles',table(['Teacher','School','Learning pathway',''],state.teachers.filter(t=>(scope==='All states'||t.state===scope)&&(!query||`${t.name} ${t.id}`.toLowerCase().includes(query.toLowerCase()))).map(t=>[link(`<strong>${t.name}</strong><small>${t.id}</small>`,go('teachers','Teacher profiles',t.id)),esc(state.schools.find(s=>s.id===t.schoolId)?.name),t.course,link('Open profile ↗',go('teachers','Teacher profiles',t.id),'text-link')])));}
function courseCards(){return `<div class="course-grid">${['Foundational literacy','Classroom practice','Inclusive learning'].map((name,i)=>`<article class="panel course"><div class="course-art art-${i}"><span>ESSENCE<br>LEARNING SERIES</span><span class="book-shape">${String(i+1).padStart(2,'0')}</span></div><div class="content"><p class="eyebrow">${i+2} MODULES · SAMPLE COURSE</p><h2>${name}</h2><p>Practical activities, guided reflection, and mentor-supported classroom application.</p><div class="course-footer">${button('Open lesson guide','course','small-btn',`data-course="${name}"`)}${link('Cohorts ↗',go('essence','Cohorts & schedule'),'text-link')}</div></div></article>`).join('')}</div>`;}
function essenceViews(){if(view==='Training hub')return `<div class="hub-hero"><div><p class="eyebrow">ESSENCE · KADUNA TEACHER CENTRE</p><h2>A place to learn.<br>A practice to take further.</h2><p>Explore demonstration courses, facilitated classroom practice, and ongoing mentor support.</p>${link('Explore cohorts →',go('essence','Cohorts & schedule'),'primary')}</div><div class="hub-number">01<span>Centre.<br>Shared ambition.</span></div></div><div class="stats">${stat('Training studios','3','Illustrative facilities')}${stat('Practice classrooms','2','Facilitated observation')}${stat('Mentor team','4','Synthetic trainer profiles')}${stat('Learning pathways','3','Sample course catalogue')}</div>${courseCards()}`;return panel(view,recordTable(selectedRecords()),view==='Cohorts & schedule'?'<span class="muted">Sample schedule · Nov 2026</span>':'');}
function energyViews(){if(view==='Site selection')return `${panel('Infrastructure priorities',mapBlock())}${schoolsView()}`;if(view==='Installation options')return `<p class="notice">Illustrative estimates only. No engineering design or commercial quote is implied.</p><div class="course-grid">${[['Essential','3 kW','2.4m','Lighting and basic ICT'],['Standard','5 kW','3.8m','Classrooms and connectivity'],['Extended','10 kW','6.2m','Broader campus requirements']].map(([name,size,price,desc],i)=>`<article class="panel content tier ${i===1?'featured':''}"><p class="eyebrow">${name.toUpperCase()}</p><h2>${size}</h2><p>${desc}</p><div class="tier-price">₦${price}<small>illustrative installed estimate</small></div><ul><li>Site audit required</li><li>Solar-hybrid configuration</li><li>Commissioning and handover</li></ul>${link('Open site assessment →',go('energy','Record','INS-001'),'primary')}</article>`).join('')}</div>`;if(view==='Monitoring')return `${panel('Operational service monitoring',`<div class="content"><p class="notice">Simulated monitoring. No live equipment connection.</p>${state.records.filter(r=>r.module==='energy'&&complete(r)).map(r=>`<div class="monitor"><h3>${r.title}</h3>${badge('Operational')}<span>Sample output 2.8 kW</span>${link('Open asset ↗',go('schools','Asset registry',r.assetId),'text-link')}</div>`).join('')||'<div class="empty">Complete commissioning to bring a demonstration installation into monitoring.</div>'}</div>`)}${assetTable(state.assets.filter(a=>(scope==='All states'||a.state===scope)&&a.name.toLowerCase().includes('solar')))}`;return panel(view,recordTable(selectedRecords()));}
function communityViews(){if(view==='Community centres')return `${panel('Community learning reach',mapBlock())}${panel('Centre directory',table(['Centre','Location','Cohort',''],[['Chikun Learning Centre','Kaduna','Foundational literacy A',link('Open referral ↗',go('community','Record','REF-001'),'text-link')],['Ibadan Learning Centre','Oyo','Numeracy bridge B',link('Open referral ↗',go('community','Record','REF-002'),'text-link')]]))}`;return `${view==='Progress & transition'?'<p class="notice">Learners use coded identifiers. Safeguarding referral details are restricted to the Community reviewer role.</p>':''}${panel(view,recordTable(selectedRecords()),view==='Progress & transition'?button('Restricted referrals','safeguarding','small-btn'):'')}`;}
function programViews(){if(view==='State scorecards')return `<div class="course-grid">${['Kaduna','Kano','Oyo'].filter(s=>scope==='All states'||s===scope).map(s=>{const rs=state.records.filter(r=>r.module==='program'&&r.state===s),n=rs.filter(complete).length;return `<article class="panel content scorecard"><p class="eyebrow">STATE SCORECARD</p><h2>${s}</h2><div class="score-value">${Math.round(n/rs.length*100)}<small>%</small></div><p>${n} of ${rs.length} illustrative results validated</p><div class="progress"><span style="width:${n/rs.length*100}%"></span></div>${button('View reporting gaps →','state-results','small-btn',`data-state="${s}"`)}</article>`}).join('')}</div>`;return panel(/^P[1-8]$/.test(entityId)?`Pillar ${entityId.slice(1)} · DLR readiness`:view,recordTable(selectedRecords()),/^P[1-8]$/.test(entityId)?link('All results →',go('program','DLR readiness'),'text-link'):'');}
function grantView(){return panel('School grants and construction',state.grants.map(g=>`<div class="content grant"><div><p class="eyebrow">${g.id} · ILLUSTRATIVE EXPENSE</p><h2>${g.title}</h2><p>${state.schools.find(s=>s.id===g.schoolId)?.name}</p></div><div><h2>${money(g.amount)}</h2>${badge(g.status)}</div><div class="milestones">${g.milestones.map((m,i)=>`<span class="${i===0||g.status==='Handed over'?'done':''}">${i+1} · ${m}</span>`).join('')}</div>${button(g.status==='Approval pending'?'Review expense':g.status==='Approved'?'Record milestone & handover':'View handover','grant','small-btn',`data-id="${g.id}"`)}</div>`).join(''));}
function missing(){return '<div class="empty"><h2>Record not found</h2><p>This link does not match a demonstration record.</p><a href="#program/Overview">Return to overview</a></div>'}
function recordDetail(){const r=state.records.find(r=>r.id===entityId&&r.module===mod);if(!r)return missing();const flow=flows[r.module],step=flow.steps[r.stage];return `<a class="back-link" href="#${go(mod,mod==='program'?'DLR readiness':mod==='schools'?'Work orders':modules[mod].views[2])}">← Back to ${modules[mod].name}</a><div class="record-banner"><div class="record-emblem">${icon(modules[mod].icon)}</div><div><p class="eyebrow">${r.id} · ${r.state.toUpperCase()}</p><h1>${esc(r.title)}</h1><p>${modules[mod].provider}</p></div>${badge(stageName(r),'neutral')}</div><div class="stepper">${flow.stages.map((s,i)=>`<div class="step ${i<=r.stage?'done':''} ${i===r.stage?'current':''}"><span>${i<r.stage?'✓':i+1}</span><small>${s}</small></div>`).join('')}</div><div class="detail-grid"><div>${panel('Record overview',`<div class="content"><dl><dt>Responsible role</dt><dd>${step?.role||'Journey complete'}</dd><dt>Location</dt><dd>${r.state}${r.schoolId?` · ${link(r.schoolId,go('schools','Schools',r.schoolId))}`:''}</dd>${r.assetId?`<dt>Asset health record</dt><dd>${link(r.assetId,go('schools','Asset registry',r.assetId))}</dd>`:''}${r.teacherId?`<dt>Teacher profile</dt><dd>${link(r.teacherId,go('teachers','Teacher profiles',r.teacherId))}</dd>`:''}<dt>Priority</dt><dd>${badge(severity(r,state))}</dd><dt>Reporting date</dt><dd>16 Nov 2026 · demonstration</dd></dl>${Object.entries(r.fields).length?`<div class="record-fields">${Object.entries(r.fields).map(([k,v])=>`<div><small>${esc(fieldLabel(r.module,k))}</small><p>${esc(v===true?'Confirmed':v)}</p></div>`).join('')}</div>`:'<p class="muted">Start the next action to capture assignment, evidence, and decisions.</p>'}</div>`)}${panel('Evidence & supporting documents',`<div class="content">${r.evidence.length?r.evidence.map((e,i)=>`<div class="file-row">${icon('document')}<div><strong>${esc(e.name)}</strong><small>${esc(e.actor)} · saved at stage ${e.stage+1}</small></div>${button('View','evidence','small-btn',`data-id="${r.id}" data-index="${i}"`)}</div>`).join(''):'<div class="empty compact">No evidence attached yet.<br><small>Evidence becomes part of the submission history.</small></div>'}</div>`)}${panel('Activity & audit history',timeline(r.audit))}</div><aside class="detail-aside">${panel(complete(r)?'Journey completed':'Next action',`<div class="content">${complete(r)?`<div class="success-mark">✓</div><h3>Progress, with proof.</h3><p>The final decision is saved. Shared records and reporting have been updated.</p>${button('Explore another journey','guide','primary')}`:`<p class="eyebrow">STEP ${r.stage+1} OF ${flow.steps.length}</p><h3>${step.label}</h3><p>Responsible role<br><strong>${step.role}</strong></p>${state.settings.role!==step.role?`<p class="notice">Your demo role is ${state.settings.role}.</p>${button(`Use ${step.role} role`,'use-role','small-btn',`data-role="${step.role}"`)}`:''}${button(`${step.label} →`,'advance','primary full',`data-id="${r.id}" ${state.settings.role!==step.role?'disabled':''}`)}${r.draft?'<small class="positive">A saved draft is available.</small>':''}${step.review?button('Return for correction','return','text-btn',`data-id="${r.id}" ${state.settings.role!==step.role?'disabled':''}`):''}`}</div>`)}<div class="demo-note">${icon('document')}<div><strong>Demonstration record</strong><p>Sample criteria and synthetic data. Actions are saved only in this browser.</p></div></div></aside></div>`;}
function fieldLabel(m,k){return flows[m].steps.flatMap(s=>s.fields).find(f=>f.key===k)?.label||k;}
function content(){const ui={button,link,table,badge,timeline,geometry:regionGeo.length?regionGeo:geo,selection:mapSelection,zoom:mapZoom};if(!allowedRoute(state,mod,view,entityId))return '<section class="panel content"><h2>Page unavailable</h2><p>This page is outside your assigned scope.</p><a class="ds-button" href="#'+activeUser(state).home+'/Overview">Go to overview</a></section>';if(isTechnician(state)){if(view==='Overview')return technicianOverview(state,ui);if(view==='Record'&&mod==='schools')return technicianDetail(state,requireJob(state,entityId),ui);if(view==='Record')return renderRolePage(state,mod,view,entityId,ui);if(view==='Settings')return technicianSettings(state);return panel('Assigned work orders',techTable(state,assignedJobs(state).filter(r=>(status==='All statuses'||severity(r,state)===status)&&(!query||`${r.id} ${r.title}`.toLowerCase().includes(query.toLowerCase()))),ui));}return renderRolePage(state,mod,view,entityId,{...ui,query,status});}
function legacyContent(){if(view==='Settings')return renderSettings({state,draft:settingsDraft,tab:settingsTabs[entityId]?entityId:'general',section:settingsSection,ui:{button,link,table,module:mod}});if(view==='Record')return recordDetail();if(view==='Overview')return overview();if(view==='Evidence')return panel('Evidence library',table(['Document','Record','Submitted by',''],state.records.filter(r=>scope==='All states'||r.state===scope).flatMap(r=>r.evidence.filter(e=>!query||`${e.name} ${r.id}`.toLowerCase().includes(query.toLowerCase())).map((e,i)=>[esc(e.name),link(r.id,recordLink(r)),esc(e.actor),button('View','evidence','small-btn',`data-id="${r.id}" data-index="${r.evidence.indexOf(e)}"`)]))));if(mod==='program')return programViews();if(mod==='schools')return view==='Schools'?schoolsView():view==='Asset registry'?assetsView():view==='Grants & projects'?grantView():panel('Maintenance work orders',recordTable(selectedRecords()));if(mod==='teachers')return teacherViews();if(mod==='energy')return energyViews();if(mod==='essence')return essenceViews();return communityViews();}
function render(){
  routes();
  if(state.settings.signedOut){$('#app').innerHTML=`<main class="demo-login align-shell"><h1>HOPE EDU</h1><h2>You’re logged out of the demo</h2><p>Your local work is saved. Choose a sample role to continue.</p><label class="field">Demo role<select id="login-role">${demoUsers.map((u,i)=>`<option value="${u.role}" ${i===0?'selected':''}>${u.label}</option>`).join('')}</select></label>${button('Enter demonstration','demo-login','ds-button ds-button-primary')}</main>`;return;}
  const tech=isTechnician(state),user=activeUser(state);

  if(view==='Settings'){settingsDraft ||= workspaceSettings(state);}else settingsDraft=null;
  document.title=`${view} · ${moduleTitles[mod]} · HOPE EDU`;
  const m=modules[mod],isOverview=view==='Overview';
  const scopeControl=`<label class="ds-select-wrap ds-scope"><span class="sr-only">State scope</span><select id="scope" aria-label="State scope">${['All states','Kaduna','Kano','Oyo'].map(s=>`<option value="${s}" ${scope===s?'selected':''}>${s==='All states'?'All States':s}</option>`).join('')}</select>${dsIcon('chevronDown')}</label>`;
  const sidebar=`<aside class="sidebar ds-sidebar ${menu?'open':''}" aria-label="Main navigation"><a class="ds-brand" href="#${user.home}/Overview">${dsIcon('logo')}<span>${esc(workspaceSettings(state).displayName)}</span></a><div class="ds-sidebar-content"><p class="ds-nav-label">Demo role</p><label class="ds-module-switch ds-select-wrap"><span class="sr-only">Select demo role</span>${dsIcon('school')}<select id="profile-role" aria-label="Select demo role">${demoUsers.map(u=>`<option value="${u.role}" ${state.settings.role===u.role?'selected':''}>${u.label}</option>`).join('')}</select>${dsIcon('chevronDown')}</label><nav aria-label="Main pages"><p class="ds-nav-label">Main</p>${roleNavigation(state).map(([m,v,label])=>`<a href="#${go(m,v,v==='Settings'?'general':'')}" class="ds-nav-item ${mod===m&&view===v?'active':''}" ${mod===m&&view===v?'aria-current="page"':''}>${dsIcon(navIcons[v]||'settings')}<span>${label}</span>${mod===m&&view===v?dsIcon('chevron'):''}</a>`).join('')}</nav></div><p class="tech-demo-label">Synthetic demonstration<br>${esc(user.state||user.schoolId||user.teacherId||(tech?'Only your assigned work':'National summaries & assigned reviews'))}</p></aside>`;
  const header=`<header class="ds-topbar">${button(icon('navigation'),'menu','ds-mobile-menu','aria-label="Toggle navigation" aria-expanded="'+menu+'"')}<h1>${esc(user.label)} workspace</h1><div class="ds-topbar-actions">${button(`${dsIcon('search')}<span>Search...</span><kbd>⌘1</kbd>`,'open-search','ds-search','aria-label="Search workspace"')}${button(icon('chat'),'messages','ds-top-icon','aria-label="Messages"')}${button(dsIcon('notifications'),'notifications','ds-top-icon','aria-label="Notifications"')}<div class="profile-control">${button(`<img class="ds-profile-image" src="/public/figma-overview/${figmaAssets.avatar}" alt="">`,'profile-toggle','profile-avatar',`aria-label="Open profile menu" aria-expanded="${profileOpen}" aria-controls="profile-dropdown"`)}${profileOpen?`<div id="profile-dropdown" class="profile-dropdown"><div class="ds-profile-copy"><strong>${esc(user.name)}</strong><small>${esc(user.label)}</small></div>${button('Profile','profile','profile-menu-item')}${link('Settings',go(tech?'schools':mod,'Settings','general'),'profile-menu-item')}${button('Logout','logout','profile-menu-item')}</div>`:''}</div></div></header>`;
  const subheader=`<section class="ds-page-header"><div><h2>${esc(view==='Record'?'Record details':roleNavigation(state).find(([m,v])=>m===mod&&v===view)?.[2]||view)}</h2><p>${esc(roleSubtitle(state,view))}</p></div></section>`;
  const body=`${false?`<div class="offline-bar">${state.settings.offline?'Offline simulation on':'Ready to sync'} · ${state.queue.length} queued change(s) ${button('Manage sync','settings','text-btn')}</div>`:''}${user.role!=='National coordinator'&&allowedRoute(state,mod,view,entityId)&&!isOverview&&view!=='Record'&&searchable()&&(!entityId||/^P[1-8]$/.test(entityId))?toolbar():''}${content()}${isOverview?'':`<footer><span>HOPE EDU · Partner engagement demonstration</span><span>Synthetic data · Not a government product</span></footer>`}`;
  $('#app').innerHTML=`<div class="align-shell technician-shell role-shell">${sidebar}<div class="main-shell ds-main-shell">${header}${subheader}<main id="main" class="ds-main ${isOverview?'is-overview':''}" tabindex="-1">${body}</main></div></div>`;
  enhanceTables($('#app'),{pageSize:state.personalPreferences?.[user.id]?.pageSize||10});
}

function formFields(step,values){return step.fields.map(f=>f.type==='checkbox'?`<label class="check-field"><input name="${f.key}" type="checkbox" ${values[f.key]?'checked':''} required><span>${f.label}</span></label>`:`<label class="field">${f.label}${f.type==='textarea'?`<textarea name="${f.key}" rows="3" required>${esc(values[f.key]||'')}</textarea>`:f.type==='select'?`<select name="${f.key}" required><option value="">Select an option</option>${f.options.map(o=>`<option value="${esc(o)}" ${values[f.key]===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input name="${f.key}" type="${f.type}" value="${esc(values[f.key]||'')}" ${f.type==='number'?'min="0" step="any"':''} required>`}</label>`).join('');}
function advanceForm(id){requireRecord(state,id,true);const r=state.records.find(r=>r.id===id),step=workflowFor(r).steps[r.stage];if(!step)return;attachments=[];openDialog(`<p class="eyebrow">${r.id} · ${step.role}</p><h2>${step.label}</h2><p class="muted">${r.title}</p><form id="workflow-form" data-id="${id}" data-version="${r.version}">${formFields(step,r.draft||{})}${step.evidence?`<div class="upload-zone">${icon('document')}<strong>Supporting evidence</strong><p>PNG, JPG, PDF or TXT · up to 2 MB each</p><input type="file" id="file" aria-label="Attach supporting evidence" accept=".png,.jpg,.jpeg,.pdf,.txt" multiple>${button('Use synthetic sample evidence','sample','small-btn')}<div id="attachment-list"></div></div>`:''}<p id="form-error" class="form-error" role="alert"></p><div class="dialog-actions">${button('Save draft','draft','small-btn',`data-id="${id}"`)}<button class="primary" type="submit">${step.label}</button></div></form>`);}
function values(form){const d=Object.fromEntries(new FormData(form));for(const c of form.querySelectorAll('[type=checkbox]'))d[c.name]=c.checked;return d;}
function renderAttachments(){$('#attachment-list').innerHTML=attachments.map((a,i)=>`<div class="file-row"><small>${esc(a.name)}</small>${button('Remove','remove-file','text-btn',`data-index="${i}"`)}</div>`).join('');}
function settings(){location.hash=go(mod,'Settings','demo');}
function guide(){openDialog(`<p class="eyebrow">SIX CONNECTED STORIES</p><h2>Explore the impact.</h2><p class="muted">Each journey takes a real delivery challenge through action, evidence, and a recorded result.</p><div class="journey-list">${Object.entries(modules).map(([k,m],i)=>{const r=state.records.find(r=>r.id===m.journey);return `<a href="#${recordLink(r)}" data-close-dialog="true"><span class="journey-no">0${i+1}</span><div><strong>${m.name}</strong><small>${r.title}</small></div><span>${r.stage}/${flows[k].steps.length} →</span></a>`}).join('')}</div>`);}
async function exportCSV(){const original=state;state=scopedData(state);try{await exportScopedCSV();}finally{state=original;}}
async function exportScopedCSV(){let rows,headers;if(view==='Schools'){headers=['ID','School','State','LGA','Condition'];rows=selectedSchools().map(s=>[s.id,s.name,s.state,s.lga,s.condition]);}else if(view==='Asset registry'){headers=['ID','Asset','School','Condition','Warranty'];rows=state.assets.filter(a=>(scope==='All states'||a.state===scope)&&(!query||`${a.name} ${a.id}`.toLowerCase().includes(query.toLowerCase()))).map(a=>[a.id,a.name,a.schoolId,a.condition,a.warranty]);}else if(view==='Teacher profiles'){headers=['ID','Teacher','State','School','Course'];rows=state.teachers.filter(t=>(scope==='All states'||t.state===scope)&&(!query||`${t.name} ${t.id}`.toLowerCase().includes(query.toLowerCase()))).map(t=>[t.id,t.name,t.state,t.schoolId,t.course]);}else if(view==='Evidence'){headers=['Record','Document','Submitted by'];rows=state.records.filter(r=>scope==='All states'||r.state===scope).flatMap(r=>r.evidence.filter(e=>!query||`${e.name} ${r.id}`.toLowerCase().includes(query.toLowerCase())).map(e=>[r.id,e.name,e.actor]));}else{headers=['ID','Title','State','Stage','Priority'];rows=selectedRecords().map(r=>[r.id,r.title,r.state,stageName(r),severity(r,state)]);}const q=x=>{let v=String(x);if(/^[=+@-]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';};const csv=[headers,...rows].map(a=>a.map(q).join(',')).join('\n');download(new Blob([csv],{type:'text/csv'}),`hope-edu-${mod}.csv`);notify('Filtered records exported.');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function evidence(id,index){const e=state.records.find(r=>r.id===id)?.evidence[index];if(!e)return;openDialog(`<p class="eyebrow">SUBMITTED EVIDENCE</p><h2>${esc(e.name)}</h2><p>${esc(e.actor)} · ${new Date(e.at).toLocaleString()}</p>${e.type.startsWith('image/')?`<img class="evidence-preview" src="${e.data}" alt="Submitted demonstration evidence">`:e.type==='text/plain'?`<pre>${esc(e.text||'Local text evidence')}</pre>`:'<p>PDF attached. Download to inspect the document.</p>'}${button('Download file','download-evidence','primary',`data-id="${id}" data-index="${index}"`)}`);}
function openOverviewReport(key, print=false) {
  const data=reportData(state,mod,scope,key);
  openDialog(`<div class="ds-report-preview"><p class="eyebrow">HOPE EDU · ${esc(data.scope)} · NOVEMBER 2026</p><h2>${data.title}</h2><p class="muted">${data.description}</p><p class="notice">Synthetic demonstration records. No live government or school reporting.</p>${table(data.columns,data.rows.map(row=>row.map(esc)))}<div class="dialog-actions">${button('Export CSV','overview-report-csv','small-btn',`data-report="${key}"`)}${button('Print / save PDF','print-report','primary')}</div></div>`);
  dialog.classList.add('report-dialog');
  if(print)window.print();
}
function exportOverviewReport(key) {
  const data=reportData(state,mod,scope,key);
  const quote=value=>{let text=String(value);if(/^[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
  download(new Blob([[data.columns,...data.rows].map(row=>row.map(quote).join(',')).join('\n')],{type:'text/csv'}),`hope-edu-${mod}-${key}.csv`);
  notify('Report exported for the selected state scope.');
}
function openWorkspaceSearch() {
  openDialog(`<p class="eyebrow">CONNECTED WORKSPACE</p><h2>${isTechnician(state)?'Find an assigned work order':'Find a school, asset or record'}</h2><label class="field"><span class="sr-only">Search workspace</span><input id="workspace-search" type="search" placeholder="Search names, IDs or locations…" autocomplete="off"></label><div id="workspace-results"></div>`);
  updateWorkspaceResults('');
  $('#workspace-search').focus();
}
function updateWorkspaceResults(term) {
  const source=isTechnician(state)?{...scopedData(state),schools:[],assets:[]}:scopedData(state);
  const searchableRecords=[...source.schools.map(s=>({title:s.name,meta:`${s.id} · ${s.state}`,href:go('schools','Schools',s.id)})),...source.assets.map(a=>({title:a.name,meta:`${a.id} · ${a.state}`,href:go('schools','Asset registry',a.id)})),...source.records.map(r=>({title:r.title,meta:`${r.id} · ${modules[r.module].name}`,href:recordLink(r)}))];
  const results=searchableRecords.filter(r=>`${r.title} ${r.meta}`.toLowerCase().includes(term.toLowerCase())).slice(0,8);
  $('#workspace-results').innerHTML=results.length?results.map(r=>`<a class="ds-search-result" data-close-dialog="true" href="#${r.href}"><span><strong>${esc(r.title)}</strong><small>${esc(r.meta)}</small></span>${dsIcon('reportChevron')}</a>`).join(''):'<p class="empty">No matching records. Try a school name or record ID.</p>';
}
function showAffectedAssets() {
  const model=overviewModel(scopedData(state),'schools','All states');
  openDialog(`<p class="eyebrow">SCHOOL OPERATIONS · ${esc(scope)}</p><h2>Assets needing attention</h2><p class="muted">Inspect the health record, report a fault, and track repair evidence.</p>${table(['Asset','Condition','School',''],model.affected.map(a=>[esc(a.name),badge(a.condition),esc(state.schools.find(s=>s.id===a.schoolId)?.name),`<a data-close-dialog="true" class="text-link" href="#schools/Asset registry/${a.id}">View asset →</a>`]))}`);
  dialog.classList.add('report-dialog');
}

document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');if(e.target.closest('[data-close-dialog]'))closeDialog();if(!a)return;const action=a.dataset.action;try{
 if(state.settings.signedOut&&action!=='demo-login')return;
 const mapActions=['map-school','map-clear','map-zoom-in','map-zoom-out','map-expand','affected-assets'];
 const mapAllowed=['State manager','Facility manager'].includes(activeUser(state).role)&&view==='Overview';
 if(mapActions.includes(action)&&!mapAllowed)throw Error('Map unavailable for this role.');
 if(action==='map-school'&&!scopedData(state).schools.some(s=>s.id===a.dataset.id))throw Error('Location unavailable.');
 const commonActions=[...(mapAllowed?mapActions:[]),'close','open-search','menu','notifications','advance','sample','remove-file','draft','evidence','download-evidence','export','profile-toggle','profile','logout','demo-login','messages','return','course','download-guide'];
 if(!commonActions.includes(action)&&!(['State manager','Facility manager'].includes(activeUser(state).role)&&['issue','grant'].includes(action)))throw Error('This action is unavailable for your role.');
 if(['advance','draft','return','evidence','download-evidence'].includes(action))requireRecord(state,a.dataset.id,['advance','draft','return'].includes(action));
 if(action==='issue'&&!scopedData(state).assets.some(x=>x.id===a.dataset.id))throw Error('Asset unavailable.');
 if(action==='grant'&&!scopedData(state).grants.some(x=>x.id===a.dataset.id))throw Error('Project unavailable.');
 if(action==='export'&&!allowedRoute(state,mod,view,entityId))throw Error('Page unavailable.');
 if(isTechnician(state)){const allowed=['close','open-search','menu','notifications','advance','sample','remove-file','draft','evidence','download-evidence','export','profile-toggle','profile','logout','demo-login','messages'];if(!allowed.includes(action))throw Error('This action is unavailable for your role.');if(['advance','draft','evidence','download-evidence'].includes(action))requireJob(state,a.dataset.id,['advance','draft'].includes(action));if(action==='export'&&(mod!=='schools'||view!=='Work orders'))throw Error('Open your assigned work orders to export.');}
 if(action==='profile-toggle'){profileOpen=!profileOpen;render();if(profileOpen)$('#profile-dropdown button')?.focus();return;}
 if(action==='profile'){profileOpen=false;render();const u=activeUser(state);openDialog(`<h2>Profile</h2><div class="settings-person"><img src="/public/figma-overview/${figmaAssets.avatar}" alt=""><div><h3>${esc(u.name)}</h3><p>${esc(u.label)}</p></div></div><p>Sample user · ${esc(u.id)}</p><p class="tech-muted">${esc(activeUser(state).state||activeUser(state).schoolId||activeUser(state).teacherId||'Assigned work and review scope')}</p>`);return;}
 if(action==='logout'){const next=structuredClone(state);next.settings.signedOut=true;await commit(next);clearUserUI();render();return;}
 if(action==='demo-login'){await switchDemoUser($('#login-role').value);return;}
 if(action==='messages'){showMessages();return;}

 if(action==='close')closeDialog();
 else if(action==='open-search')openWorkspaceSearch();
 else if(action==='map-school'){mapSelection=a.dataset.id;render();document.querySelector(`[data-action="map-school"][data-id="${mapSelection}"]`)?.focus();}
 else if(action==='map-clear'){mapSelection='';render();}
 else if(action==='map-zoom-in'||action==='map-zoom-out'){mapZoom=Math.min(1.8,Math.max(1,mapZoom+(action==='map-zoom-in'?.2:-.2)));render();}
 else if(action==='map-expand'){const panel=document.querySelector('.ds-map-panel');panel.classList.toggle('expanded');a.setAttribute('aria-label',panel.classList.contains('expanded')?'Collapse map':'Expand map');}
 else if(action==='affected-assets')showAffectedAssets();
 else if(action==='overview-report')openOverviewReport(a.dataset.report);
 else if(action==='overview-report-pdf')openOverviewReport(a.dataset.report,true);
 else if(action==='overview-report-csv')exportOverviewReport(a.dataset.report);
 else if(action==='print-report')window.print();
 else if(action==='menu'){menu=!menu;render();}
 else if(action==='guide')guide();
 else if(action==='settings')settings();
 else if(action==='settings-section'){settingsSection=a.dataset.section;render();}
 else if(action==='settings-discard'){settingsDraft=workspaceSettings(state);render();notify('Unsaved settings discarded.');}
 else if(action==='settings-remove-logo'){settingsDraft.logo='';render();}
 else if(action==='scope'){scope=a.dataset.state;render();}
 else if(action==='state-results'){scope=a.dataset.state;location.hash=go('program','DLR readiness');}
 else if(action==='notifications'){const rs=scopedData(state).records.filter(r=>!complete(r));openDialog(`<p class="eyebrow">YOUR ATTENTION</p><h2>Work moving forward</h2><p class="muted">${isTechnician(state)?'Open work orders assigned to you.':'Open actions within your assigned scope.'}</p>${recordTable(rs.slice(0,8))}`);}
 else if(action==='use-role'){const next=structuredClone(state);next.settings.role=a.dataset.role;await commit(next);render();notify(`Demo role: ${a.dataset.role}`);}
 else if(action==='advance')advanceForm(a.dataset.id);
 else if(action==='sample'){attachments.push({name:'Synthetic supporting evidence.txt',type:'text/plain',text:'DEMONSTRATION ONLY\nSynthetic evidence supporting the selected record. No real individuals, schools, approvals, or government records are represented.',data:'data:text/plain;base64,'+btoa('DEMONSTRATION ONLY\nSynthetic supporting evidence. No actual government records.')});renderAttachments();}
 else if(action==='remove-file'){attachments.splice(Number(a.dataset.index),1);renderAttachments();}
 else if(action==='draft'){const form=$('#workflow-form'),next=structuredClone(state),r=next.records.find(r=>r.id===a.dataset.id);r.draft=values(form);await commit(next);closeDialog();render();notify('Draft saved. Attachments are added when submitting.');}
 else if(action==='return'){openDialog(`<h2>Return for correction</h2><p class="muted">The previous step will reopen. Existing evidence and decisions stay in the audit history.</p><form id="return-form" data-id="${a.dataset.id}"><label class="field">Reason<textarea name="reason" required></textarea></label><p class="form-error" role="alert"></p><button class="primary" type="submit">Return record</button></form>`);}
 else if(action==='evidence')evidence(a.dataset.id,Number(a.dataset.index));
 else if(action==='download-evidence'){const ev=state.records.find(r=>r.id===a.dataset.id).evidence[Number(a.dataset.index)];const blob=await(await fetch(ev.data)).blob();download(blob,ev.name);}
 else if(action==='copy-link'){await navigator.clipboard.writeText(location.href);notify('Asset link copied.');}
 else if(action==='export')await exportCSV();
 else if(action==='definitions')openDialog('<p class="eyebrow">DEMONSTRATION DEFINITIONS</p><h2>Understand the numbers.</h2><dl><dt>Evidence readiness</dt><dd>Validated DLR records divided by all DLR records in the selected state scope.</dd><dt>Warning</dt><dd>An initial reporting or operational step remains open.</dd><dt>Critical</dt><dd>The recorded deadline is before the fixed demonstration date, 16 November 2026.</dd><dt>Normal</dt><dd>A completed record or an in-progress record without the above flags.</dd></dl><p class="notice">Eight pillars and 28 results are illustrative placeholders, not verified government program definitions.</p>');
 else if(action==='course'){openDialog(`<p class="eyebrow">SAMPLE LEARNING GUIDE</p><h2>${esc(a.dataset.course)}</h2><p>This demonstration lesson is a placeholder for approved training material.</p><ol class="lesson"><li>Plan a ten-minute guided reading activity.</li><li>Invite learners to explain their reasoning.</li><li>Record a reflection on participation and understanding.</li><li>Discuss one adjustment with your mentor.</li></ol>${button('Download for offline use','download-guide','primary',`data-course="${a.dataset.course}"`)}<p>${link('Open teacher training journey →',go('teachers','Record','OBS-001'),'text-link')}</p>`);}
 else if(action==='download-guide'){download(new Blob([`SAMPLE GUIDE — ${a.dataset.course}\nDemonstration content only.\n1. Plan guided reading.\n2. Encourage reasoning.\n3. Record reflection.\n4. Discuss with mentor.`],{type:'text/plain'}),'sample-lesson-guide.txt');notify('Sample guide downloaded for offline reading.');}
 else if(action==='safeguarding'){openDialog(state.settings.role==='Community reviewer'?'<p class="eyebrow">RESTRICTED DEMONSTRATION VIEW</p><h2>Safeguarding referrals</h2><p>No active safeguarding cases in the synthetic dataset.</p><p class="notice">Production referral handling and access policies remain to be defined.</p>':'<h2>Restricted access</h2><p>Only the Community reviewer role can open this view. Ordinary cohort records do not contain referral details.</p>');}
 else if(action==='sync'){if(state.settings.offline)throw Error('Turn off offline simulation first.');const next=structuredClone(state);next.queue=[];await commit(next);render();notify('Simulated sync completed. Local records retained.');}
 else if(action==='conflict'){openDialog(`<h2>Resolve a simulated conflict</h2><p>A demonstration server copy has an older record version. Your local data has the changes made in this session.</p><dl><dt>Local version</dt><dd>Current saved record and its audit history</dd><dt>Simulated server version</dt><dd>Previous version; no live server exists</dd></dl>${button('Keep local version and retry','resolve-conflict','primary')}${button('Cancel and keep queued','close','small-btn')}`);}
 else if(action==='resolve-conflict'){const next=structuredClone(state);next.queue=[];await commit(next);closeDialog();render();notify('Local version retained. Simulated sync completed.');}
 else if(action==='reset'){openDialog(`<h2>Reset the demonstration?</h2><p>This removes your local changes, drafts, and attached files. The original synthetic records will be restored.</p><div class="dialog-actions">${button('Cancel','close','small-btn')}${button('Reset demonstration','confirm-reset','danger-btn')}</div>`);}
 else if(action==='confirm-reset'){await commit(addTechnicianFixtures(seed()));scope='All states';query='';status='All statuses';closeDialog();location.hash='program/Overview';render();notify('Demonstration reset.');}
 else if(action==='issue'){const asset=state.assets.find(x=>x.id===a.dataset.id),existing=state.records.find(r=>r.assetId===asset.id&&r.module==='schools'&&!complete(r));if(existing){location.hash=recordLink(existing);return;}openDialog(`<h2>Report service issue</h2><p>${esc(asset.name)} · ${asset.id}</p><form id="issue-form" data-id="${asset.id}"><label class="field">Issue description<textarea name="title" required></textarea></label><p class="form-error" role="alert"></p><button class="primary" type="submit">Create work order</button></form>`);}
 else if(action==='grant'){const g=state.grants.find(g=>g.id===a.dataset.id);openDialog(`<p class="eyebrow">${g.id} · DEMONSTRATION</p><h2>${g.title}</h2><p>${money(g.amount)} · ${badge(g.status)}</p>${g.status==='Handed over'?`<p>${esc(g.notes)}</p><p>Recorded by ${esc(g.actor)}</p>`:`<form id="grant-form" data-id="${g.id}"><p class="notice">${g.status==='Approval pending'?'State manager':'Facility manager'} role required.</p><label class="field">${g.status==='Approval pending'?'Approval reason':'Milestone and handover evidence notes'}<textarea name="notes" required></textarea></label><label class="check-field"><input type="checkbox" name="confirmed" required> I reviewed the sample requirements</label><p class="form-error" role="alert"></p><button class="primary" type="submit" ${state.settings.role===(g.status==='Approval pending'?'State manager':'Facility manager')?'':'disabled'}>${g.status==='Approval pending'?'Approve expense':'Verify handover'}</button></form>`}`);}
 }catch(error){notify(error.message);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['tech-preferences','message-form','workspace-settings-form','workflow-form','return-form','issue-form','grant-form'].includes(f.id))return;e.preventDefault();const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
 if(state.settings.signedOut)throw Error('Choose a demo user first.');
 if(!['tech-preferences','message-form','workflow-form','return-form','issue-form','grant-form'].includes(f.id))throw Error('This action is unavailable for your role.');
 if(f.id==='tech-preferences'){const prefs=values(f);if(!['Africa/Lagos','Asia/Qatar','UTC'].includes(prefs.timezone)||![10,25,50].includes(Number(prefs.pageSize)))throw Error('Choose valid display preferences.');const next=structuredClone(state);next.personalPreferences||={};next.personalPreferences[activeUser(state).id]={timezone:prefs.timezone,pageSize:Number(prefs.pageSize)};await commit(next);render();notify('Personal preferences saved.');}
 if(f.id==='message-form'){const v=values(f);if(!['state-001','facility-001'].includes(v.recipient)||!v.message?.trim()||v.message.length>2000)throw Error('Choose a contact and enter up to 2,000 characters.');const next=structuredClone(state);next.messages||=[];next.messages.push({senderId:activeUser(state).id,recipientId:v.recipient,text:v.message.trim(),at:new Date().toISOString()});await commit(next);showMessages();}
 if(['workflow-form','return-form'].includes(f.id))requireRecord(state,f.dataset.id,true);
 if(f.id==='issue-form'&&(!['Facility manager','State manager'].includes(activeUser(state).role)||!scopedData(state).assets.some(a=>a.id===f.dataset.id)))throw Error('Asset unavailable.');
 if(f.id==='grant-form'&&!scopedData(state).grants.some(g=>g.id===f.dataset.id))throw Error('Project unavailable.');

 if(f.id==='workspace-settings-form'){await commit(applyWorkspaceSettings(state,settingsDraft));settingsDraft=workspaceSettings(state);render();notify('Workspace settings saved.');}
 if(f.id==='workflow-form'){await commit(transition(state,f.dataset.id,state.settings.role,values(f),{evidence:attachments,expectedVersion:Number(f.dataset.version)}));closeDialog();render();notify(state.settings.offline?'Saved locally. Change queued for simulated sync.':'Record updated. Audit history saved.');}
 if(f.id==='return-form'){await commit(transition(state,f.dataset.id,state.settings.role,{}, {returnReason:values(f).reason}));closeDialog();render();notify('Record returned with feedback.');}
 if(f.id==='issue-form'){if(!['Facility manager','State manager','Auroch manager'].includes(state.settings.role))throw Error('Use Facility manager, State manager, or Auroch manager to report an issue.');const next=structuredClone(state),asset=next.assets.find(a=>a.id===f.dataset.id),id=`WO-${Date.now().toString().slice(-6)}`;next.records.push({id,module:'schools',title:values(f).title,state:asset.state,schoolId:asset.schoolId,assetId:asset.id,stage:0,version:1,roleVersion:2,fields:{},evidence:[],audit:[{label:'Service issue reported',actor:state.settings.role,at:new Date().toISOString()}]});asset.condition='Failed';await commit(next);closeDialog();location.hash=go('schools','Record',id);notify('Work order created.');}
 if(f.id==='grant-form'){const next=structuredClone(state),g=next.grants.find(g=>g.id===f.dataset.id);if(!['Approval pending','Approved'].includes(g.status))throw Error('This project decision is already complete.');if(!values(f).confirmed||!values(f).notes?.trim())throw Error('Confirm the review and add decision notes.');const role=g.status==='Approval pending'?'State manager':'Facility manager';if(state.settings.role!==role)throw Error(`Use the ${role} role.`);g.status=g.status==='Approval pending'?'Approved':'Handed over';g.notes=values(f).notes;g.actor=state.settings.role;g.at=new Date().toISOString();await commit(next);closeDialog();render();notify('Project decision saved.');}
 }catch(error){f.querySelector('.form-error').textContent=error.message;if(submit)submit.disabled=false;}});
document.addEventListener('change',async e=>{const el=e.target;try{if(state.settings.signedOut&&el.id!=='login-role')return;if(['scope','module-switch','lga','role','offline','settings-logo'].includes(el.id))throw Error('This setting is unavailable for your role.');if(el.closest('#workspace-settings-form')&&el.name){settingsDraft[el.name]=el.value;}if(el.id==='settings-logo'){const file=el.files?.[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>1024*1024)throw Error('Choose a PNG or JPEG smaller than 1 MB.');settingsDraft.logo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the image.'));reader.readAsDataURL(file);});render();}if(el.id==='scope'){scope=el.value;lga='All LGAs';mapSelection='';mapZoom=1;render();}if(el.id==='module-switch'){location.hash=go(el.value);}if(el.id==='status'){status=el.value;render();}if(el.id==='lga'){lga=el.value;render();}if(el.id==='profile-role'){await switchDemoUser(el.value);return;}if(el.id==='role'||el.id==='offline'){const next=structuredClone(state);if(el.id==='role')next.settings.role=el.value;else next.settings.offline=el.checked;await commit(next);render();}if(el.id==='file'){const staged=[];for(const file of el.files){if(file.size>2*1024*1024)throw Error('Each attachment must be 2 MB or smaller.');if(!['image/png','image/jpeg','application/pdf','text/plain'].includes(file.type))throw Error('Choose PNG, JPG, PDF, or TXT evidence.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});staged.push({name:file.name,type:file.type,data,text:file.type==='text/plain'?await file.text():undefined});}attachments.push(...staged);renderAttachments();}}
 catch(error){notify(error.message)}});
document.addEventListener('input',e=>{if(e.target.closest('#workspace-settings-form')&&e.target.name)settingsDraft[e.target.name]=e.target.value;if(e.target.id==='workspace-search')updateWorkspaceResults(e.target.value);if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();const s=$('#search');s.focus();s.setSelectionRange(pos,pos);}});
window.addEventListener('hashchange',()=>{if(dialog.open)closeDialog();menu=false;profileOpen=false;query='';status='All statuses';render();window.scrollTo(0,0);});
try{[state,geo,regionGeo]=await Promise.all([openStore(),fetch('/public/nigeria.json').then(r=>r.json()).catch(()=>[]),fetch('/public/nigeria-region.json').then(r=>r.json()).catch(()=>[])]);if(!location.hash)scope=workspaceSettings(state).defaultScope;render();}catch(error){$('#app').innerHTML=`<div class="boot"><h1>Workspace could not open</h1><p>${esc(error.message)}</p><p>Browser storage must be available to save demonstration records.</p><button onclick="location.reload()">Try again</button></div>`;}

document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='1'){e.preventDefault();if(!state.settings.signedOut)openWorkspaceSearch();}if(e.key==='Escape'&&profileOpen){profileOpen=false;render();document.querySelector('[data-action=profile-toggle]')?.focus();}if(e.key==='Escape')document.querySelector('.ds-map-panel.expanded')?.classList.remove('expanded');if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action=map-school]')){e.preventDefault();e.target.dispatchEvent(new Event('click',{bubbles:true}));}});

function clearUserUI(){if(dialog.open)closeDialog();dialog.innerHTML='';profileOpen=false;menu=false;query='';scope='All states';lga='All LGAs';status='All statuses';settingsDraft=null;settingsSection='details';attachments=[];mapSelection='';$('#toast').textContent='';}
async function switchDemoUser(role,id){const user=id?allUsers.find(u=>u.id===id&&u.role===role):demoUsers.find(u=>u.role===role);if(!user)throw Error('Choose one of the five demo roles.');const next=structuredClone(state);next.settings.role=role;next.settings.activeUserId=user.id;next.settings.signedOut=false;await commit(next);clearUserUI();location.hash=go(user.home);render();}
function showMessages(){const u=activeUser(state),messages=(state.messages||[]).filter(m=>m.senderId===u.id);openDialog(`<h2>Messages</h2><p class="notice">Local chat demonstration. Messages are saved in this browser only; no live delivery or replies.</p><div class="chat-history" aria-live="polite">${messages.length?messages.map(m=>`<article class="chat-bubble"><small>To ${esc(demoUsers.find(x=>x.id===m.recipientId)?.name)} · saved locally</small><p>${esc(m.text)}</p></article>`).join(''):'<p class="empty">Start a conversation with your service team.</p>'}</div><form id="message-form"><label class="field">Contact<select name="recipient"><option value="state-001">Amina Yusuf · State Manager</option><option value="facility-001">Musa Ibrahim · Facility Manager</option></select></label><label class="field">Message<textarea name="message" required maxlength="2000" placeholder="Write about your assigned work…"></textarea></label><p class="form-error" role="alert"></p><button type="submit" class="ds-button ds-button-primary">Send demo message</button></form>`);}
document.addEventListener('click',e=>{if(profileOpen&&!e.target.closest('.profile-control')){profileOpen=false;const drop=$('#profile-dropdown');drop?.remove();document.querySelector('[data-action=profile-toggle]')?.setAttribute('aria-expanded','false');}});
